<div x-data="{ department: @js((string) old('department_id', '')), recipient: @js((string) old('recipient_id', '')), users: @js($recipients) }" class="space-y-5">
<div><label for="department_id" class="block text-sm font-medium">Destination department</label><select id="department_id" name="department_id" x-model="department" @change="recipient = ''" required class="mt-2 w-full rounded-lg border-slate-300"><option value="">Select department</option>@foreach($departments as $department)<option value="{{ $department->id }}">{{ $department->name }}</option>@endforeach</select></div>
<div><label for="recipient_id" class="block text-sm font-medium">Recipient employee</label><select id="recipient_id" name="recipient_id" x-model="recipient" :disabled="!department" required class="mt-2 w-full rounded-lg border-slate-300 disabled:bg-slate-100"><option value="">Select recipient</option><template x-for="user in users.filter(user => String(user.department_id) === department)" :key="user.id"><option :value="String(user.id)" x-text="user.name"></option></template></select><p class="mt-2 text-xs text-slate-500">Only active employees and administrators in the selected active department are available.</p></div>
</div>
